import {escapeHtml as h,number} from './domain.js';
import {planetArt,badge,civilizationBadge,shipArt} from './art.js';
import {recentBattlesView} from './reports.js';
const pop=n=>new Intl.NumberFormat('en',{notation:'compact',minimumFractionDigits:1,maximumFractionDigits:2}).format(Number(n)||0);
const fields=[['soldiers','Soldats'],['scouts','Scouts'],['bombers','Bombardiers'],['fighters','Destroyers']];
export function sumForces(forces){return forces.reduce((t,f)=>{for(const k of ['scouts','bombers','fighters'])t[k]+=Number(f[k])||0;t.ground+=Number(f.ground_soldiers)||0;t.embarked+=Number(f.soldiers)||0;t.soldiers=t.ground+t.embarked;if(f.kind==='fleet'&&Number(f.scouts)+Number(f.bombers)+Number(f.fighters)>0)t.fleets++;return t;},{soldiers:0,scouts:0,bombers:0,fighters:0,ground:0,embarked:0,fleets:0});}
export function forceCamps(p){const side=p.stance==='attack'?'attack':'defend',forces=p.forces||[];return {own:sumForces(forces.filter(f=>f.is_own)),allies:sumForces(forces.filter(f=>!f.is_own&&f.mission===side)),enemies:sumForces(forces.filter(f=>!f.is_own&&f.mission!==side))};}
const hasForces=t=>fields.some(([key])=>Number(t?.[key])>0);
function foreignCampRows(title,tone,p,detailed){
 const side=p.stance==='attack'?'attack':'defend';
 const forces=(p.forces||[]).filter(f=>!f.is_own&&(tone==='allied'?f.mission===side:f.mission!==side));
 return ['elys','vael','khar'].map(race=>{const total=sumForces(forces.filter(f=>(f.race||p.race)===race));return hasForces(total)?forcesRow(title,total,tone,race,detailed,true):'';}).join('');
}
function forcesRow(title,t,tone,race,detailed,showRace=false){return `<div class="overview-force ${tone}"><b class="force-label">${title}${showRace?`<span class="force-race">${badge('race',race)}${h(race.charAt(0).toUpperCase()+race.slice(1))}</span>`:''}</b><span class="force-count">${number(t.fleets)} flotte${t.fleets>1?'s':''}</span><div class="overview-units">${fields.map(([k,label])=>`<span title="${label}" aria-label="${number(t[k])} ${label}">${k==='soldiers'?badge('race',race):shipArt(race,k==='scouts'?'scout':k==='bombers'?'bomber':'fighter')}<strong>${number(t[k])}</strong>${detailed?`<small>${label}</small>`:''}</span>`).join('')}</div>${detailed?`<small>${number(t.ground)} au sol · ${number(t.embarked)} embarqués</small>`:''}</div>`;}
function traits(p){return `<div class="overview-traits">${badge('race',p.race)}${badge('resource',p.resource)}<span>${badge('pop',p.race)}${pop(p.population)}</span><span>${civilizationBadge()}<b>${number(p.civilization)}</b></span></div>`;}
function worldCard(p,data,detailed){
 const camps=forceCamps(p),own=(data.planets||[]).find(w=>w.id===p.id),jobs=(data.jobs||[]).filter(j=>j.planet_id===p.id),busy=jobs.filter(j=>j.kind!=='factory').length;
 const total=Number(p.trade_capacity)||0,used=Number(p.trade_exploited)||0,energy=Math.max(0,Number(own?.energy)||0),energyMax=Math.max(1,Number(own?.energy_max)||10);
 const status=p.is_own?'Sous contrôle':p.stance==='mixed'?'Attaque & défense':p.stance==='attack'?'En attaque':'En défense';
 return `<article class="overview-world ${p.stance==='attack'||p.stance==='mixed'?'hostile-world':''}"><button class="overview-world-link" data-page="fleets" data-military-location="${h(p.id)}" aria-label="Gérer les forces sur ${h(p.name)}"><img class="overview-planet" src="${planetArt(p.appearance||p.race+'_'+p.resource)}" alt="" width="82" height="82"><span><small>${status}</small><h3>${h(p.name)}</h3>${traits(p)}</span><span class="overview-arrow" aria-hidden="true">↗</span></button>${p.is_own&&!detailed?`<div class="overview-trade"><span>Commerce <b>${number(used)} / ${number(total)}</b></span><progress value="${used}" max="${Math.max(1,total)}" aria-label="Capacités commerciales exploitées"></progress></div><div class="overview-trade overview-energy"><span>Énergie <b>${number(energy)} / ${number(energyMax)}</b></span><progress value="${Math.min(energy,energyMax)}" max="${energyMax}" aria-label="Énergie disponible"></progress></div>`:''}<div class="overview-camps">${forcesRow('Vos forces',camps.own,'own',p.race,detailed)}${foreignCampRows(p.stance==='mixed'?'Autres en défense':'Alliés','allied',p,detailed)}${foreignCampRows(p.stance==='mixed'?'Autres en attaque':'Ennemis','hostile',p,detailed)}</div>${detailed&&own?`<div class="overview-industry"><span><b>${number(own.factories)}</b> usines <small>· ${number(Math.max(0,own.factories-busy))} libres</small></span><div>${jobs.length?['scout','bomber','fighter','factory'].map(kind=>{const batch=jobs.filter(j=>j.kind===kind);if(!batch.length)return '';const first=batch.reduce((a,b)=>a.finishes_at<b.finishes_at?a:b);return `<span class="production-chip"><b>${batch.length}</b> ${({scout:'scout(s)',bomber:'bombardier(s)',fighter:'destroyer(s)',factory:'usine'})[kind]} <small>${batch.some(j=>j.paused_at)?'En pause':`Prochaine fin : ${h(new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(first.finishes_at)))}`}</small></span>`;}).join(''):'<small>Aucune production en cours</small>'}</div></div>`:''}</article>`;
}
export function commandPlanetOverview(data){const worlds=(data?.locations||[]).filter(p=>p.is_own);return `<section class="world-overview"><div class="military-section-heading"><h2>Planètes sous contrôle</h2><span>${worlds.length} mondes</span></div><div class="overview-grid">${worlds.map(p=>worldCard(p,data,false)).join('')}</div></section>`;}
function militaryWorldCard(p,data){
 const totals=forceCamps(p),own=(data.planets||[]).find(w=>w.id===p.id),jobs=(data.jobs||[]).filter(j=>j.planet_id===p.id&&j.kind!=='factory').sort((a,b)=>new Date(a.finishes_at)-new Date(b.finishes_at));
 const side=p.stance==='attack'?'attack':'defend';
 const camps=[{key:'own',name:'Vous',tone:'own',match:f=>f.is_own},...(hasForces(totals.allies)?[{key:'allies',name:p.stance==='mixed'?'Autres : défense':'Alliés',tone:'allied',match:f=>!f.is_own&&f.mission===side}]:[]),...(hasForces(totals.enemies)?[{key:'enemies',name:p.stance==='mixed'?'Autres : attaque':'Ennemis',tone:'hostile',match:f=>!f.is_own&&f.mission!==side}]:[])];
 const unitCount=(f,key)=>key==='soldiers'?Number(f.soldiers||0)+Number(f.ground_soldiers||0):Number(f[key]||0);
 const rows=fields.map(([key,label])=>{
  const races=['elys','vael','khar'].map(race=>({race,counts:camps.map(c=>(p.forces||[]).filter(f=>c.match(f)&&(f.race||p.race)===race).reduce((n,f)=>n+unitCount(f,key),0))})).filter(r=>r.counts.some(n=>n>0));
  return `<details class="military-unit-row"><summary class="military-matrix-row"><span class="military-unit-label"><i aria-hidden="true">›</i>${key==='soldiers'?badge('race',p.race):shipArt(p.race,key==='scouts'?'scout':key==='bombers'?'bomber':'fighter')}<span>${label}</span></span>${camps.map(c=>`<b class="${c.tone} ${totals[c.key][key]?'':'is-zero'}">${number(totals[c.key][key])}</b>`).join('')}</summary><div class="military-unit-breakdown">${races.length?races.map(r=>`<div class="military-matrix-row"><span class="force-race">${badge('race',r.race)}${h(r.race.charAt(0).toUpperCase()+r.race.slice(1))}</span>${r.counts.map((n,i)=>`<span class="${camps[i].tone} ${n?'':'is-zero'}">${n?number(n):'—'}</span>`).join('')}</div>`).join(''):'<p>Aucune unité de cette catégorie.</p>'}</div></details>`;
 }).join('');
 const status=p.is_own?'Sous contrôle':p.stance==='mixed'?'Attaque & défense':p.stance==='attack'?'En attaque':'En défense';
 const nav=`data-page="fleets" data-military-location="${h(p.id)}"`;
 const head=jobs[0],now=new Date(head?.paused_at||data.server_now||Date.now()),progress=head?Math.max(0,Math.min(100,(now-new Date(head.started_at))/(new Date(head.finishes_at)-new Date(head.started_at))*100)):0;
 const stasis=data.technology?.special?.planets?.find(w=>w.id===p.id)?.project?.stasis,speed=Number(own?.factories||0)/5*(p.resource==='ferros'?1.15:1)/(stasis?3:1);
 const production=jobs.length?['scout','bomber','fighter'].map(kind=>{const count=jobs.filter(j=>j.kind===kind).length;return count?`<span class="yard-production-chip">${shipArt(p.race,kind)}<b>${number(count)}</b><span>${({scout:'Scouts',bomber:'Bombardiers',fighter:'Destroyers'})[kind]}</span>`:'';}).join(''):'<span class="yard-idle">Aucune production en cours</span>';
 return `<article class="military-world-card ${p.stance==='attack'||p.stance==='mixed'?'hostile-world':''}" style="--camp-count:${camps.length}"><header class="military-card-header"><button class="military-card-identity" ${nav} aria-label="Gérer les forces sur ${h(p.name)}"><img src="${planetArt(p.appearance||p.race+'_'+p.resource,true)}" alt="" width="60" height="60"><span><small>${status} · ${number(totals.own.fleets)} flotte${totals.own.fleets>1?'s':''}</small><h3>${h(p.name)}</h3><span class="military-world-traits">${badge('race',p.race)}${badge('resource',p.resource)}</span></span></button><div class="military-card-chips"><span title="${number(p.population)} habitants">${badge('pop',p.race)}${pop(p.population)}</span><span>${civilizationBadge()}${number(p.civilization)}</span></div></header><div class="military-force-matrix"><div class="military-matrix-row military-camp-head"><span class="visually-hidden">Vos forces et forces présentes</span>${camps.map(c=>`<span class="${c.tone}">${c.name}</span>`).join('')}</div>${rows}<div class="military-ground-note"><span>${number(totals.own.ground)} au sol</span><span>${number(totals.own.embarked)} embarqués</span></div></div>${own?`<section class="military-yard"><div class="military-yard-heading"><strong>${number(own.factories)}</strong><span>Usines<small>Vitesse ×${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(speed)}</small></span><span class="yard-queue-count">${number(jobs.length)} en file</span></div><div class="yard-production">${production}</div>${head?`<div class="yard-progress"><progress value="${progress}" max="100" aria-label="Progression du prochain vaisseau"></progress><small>${head.paused_at?'Production suspendue':`Prochaine unité : ${h(new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(head.finishes_at)))}`}</small></div>`:''}<button class="secondary" ${nav}>Gérer les chantiers →</button></section>`:`<footer class="military-card-footer"><button class="secondary" ${nav}>Gérer les forces →</button></footer>`}</article>`;
}
export function militaryOverviewView(data,pending){return `<div class="military-overview">${pending?'<div class="document-panel"><p>Un ordre attend sa confirmation.</p><button id="retry-military" class="secondary">Vérifier cet ordre</button></div>':''}<div class="military-section-heading"><div><h2>Vos positions militaires</h2><span class="military-overview-hint">Dépliez une catégorie pour le détail par race.</span></div><button class="secondary" data-page="transit">Flottes en transit →</button></div><div class="military-overview-grid">${(data?.locations||[]).map(p=>militaryWorldCard(p,data)).join('')||'<p class="empty">Aucune position militaire.</p>'}</div>${recentBattlesView(data)}</div>`;}
